# Code generated by Claude
# The full test suite, one test after the other (one MuJoCo process at a time), with a log per test and a summary file.
# usage (in a detached tmux session, rule 3 of CLAUDE.md):  [SKIP="test_a test_b"] bash experiments/run_tests.sh [TAG]      (TAG defaults to the time stamp; SKIP lists tests to leave out, e.g. ones already run)
# Writes data/logs/suite_<TAG>_summary.txt ("=== <name> start/exit <code> at <time>: <last line of its log>", then ALL_DONE) and data/logs/suite_<TAG>_<name>.log.
# A test passes if its exit code is 0. About an hour in all (cc_mode_tests alone is about 20 minutes).
cd "$(dirname "$0")/.."
source .venv/bin/activate
export MUJOCO_GL=egl
TAG=${1:-$(date +%Y%m%d_%H%M%S)}
SUM=data/logs/suite_${TAG}_summary.txt
run() {
  name=$1; shift
  echo "=== $name start $(date +%T)" >> "$SUM"
  "$@" > "data/logs/suite_${TAG}_${name}.log" 2>&1
  code=$?
  echo "=== $name exit $code at $(date +%T): $(grep -E 'checks passed|cases|PASS|FAIL|Error' "data/logs/suite_${TAG}_${name}.log" | tail -1 | cut -c1-160)" >> "$SUM"
}
for t in arm_kinematics_test grasp_rules_test arm_collision_test gripper_geometry_test furniture_map_test stance_finder_test pour_scene_test home_pose_test face_test \
         gripper_force_test grasp_lift_test beaker_hollow_test target_mode_test sequential_policy_test beaker_hotplate_correction_test beaker_hotplate_success_test \
         pedestal_lift_test rest_contacts_test robot_vs_urdf_test reach_map_holes_test reach_map_restamp cc_loop_tests cc_mode_tests mpvi_postprocess_test grounding_test llm_calls_test vlm_checker_test orchestrator_retry_test mpvi_monitor_test full_check_test nav_core_test nav_follow_test nav_follow_sim_test nav_pipeline_follow_test stance_select_test stance_select_pipeline_test stance_select_pipeline_test_task_cfg stance_select_moved_test bench_stance_test support_test mpvi_pipeline_test mpvi_pipeline_test_bench_region mpvi_text_test; do
  case " $SKIP " in *" $t "*) echo "=== $t SKIPPED (env SKIP)" >> "$SUM"; continue;; esac
  case "$t" in nav_core_test) run "$t" python experiments/$t.py --sim;; reach_map_restamp) run "$t" python experiments/$t.py --check;; nav_follow_sim_test) run "$t" python experiments/$t.py --only on;;
    stance_select_pipeline_test_task_cfg) run "$t" python experiments/stance_select_pipeline_test.py --stance-mode task_cfg;; mpvi_pipeline_test_bench_region) run "$t" python experiments/mpvi_pipeline_test.py --stance-mode bench_region;; *) run "$t" python experiments/$t.py;; esac
done
run safety_filter_model_check python experiments/safety_filter_roundtrip.py --model-check
echo ALL_DONE >> "$SUM"
